func:
// A command addressed to this companion. Decide, then answer: every
// command earns a COMMAND_ACK, so the sender's retry loop stops.

// Never act on a frame admitted despite a bad signature.
if (msg.trusted === false) return null;

const MAV_CMD_USER_1 = 31010;
const ACCEPTED = 0;
const UNSUPPORTED = 3;

const command = msg.payload.command;
const result = command === MAV_CMD_USER_1 ? ACCEPTED : UNSUPPORTED;
node.status({ text: `cmd ${command} → ${result === ACCEPTED ? 'accepted' : 'unsupported'}` });

return {
    topic: 'COMMAND_ACK',
    payload: {
        command,
        result,
        progress: 0,
        result_param2: 0,
        // The ack's own target is whoever sent the command — mavlink-in put
        // the sender's ids on the message. MAVLink 2 extension fields; a
        // MAVLink 1 peer never sees them and matches on `command` alone.
        // The frame itself rides the connection's configured remote — a
        // GCS endpoint is never learned (§8) — so that remote must be the GCS.
        target_system: msg.sysid,
        target_component: msg.compid,
    },
};
